import assert from 'node:assert/strict';
import fs from 'node:fs';
import vm from 'node:vm';
import ts from 'typescript';
const src=fs.readFileSync('src/lib/purchaseOrderCostSnapshot.ts','utf8');
const module={exports:{}};
vm.runInNewContext(ts.transpileModule(src,{compilerOptions:{module:ts.ModuleKind.CommonJS}}).outputText,{module,exports:module.exports});
const {snapshotPurchaseOrderLine,preservePurchaseOrderOnVendorUpdate,recordActualPurchaseCost,purchaseCostVariance,snapshotPersistedPurchaseOrderLine,preservePersistedPurchaseOrderOnVendorUpdate}=module.exports;
const po=snapshotPurchaseOrderLine({quantity:3,unit_cost:325,extended_cost:0});
assert.equal(po.extended_cost,975);
const afterVendorChange=preservePurchaseOrderOnVendorUpdate(po);
assert.equal(afterVendorChange.unit_cost,325);
assert.equal(afterVendorChange.extended_cost,975);
const received=recordActualPurchaseCost(afterVendorChange,350);
assert.equal(received.unit_cost,325);
assert.equal(received.actual_unit_cost,350);
assert.equal(purchaseCostVariance(received),75);
assert.equal(purchaseCostVariance(po),null);
assert.throws(()=>recordActualPurchaseCost(po,-1),/Invalid/);
const persisted=snapshotPersistedPurchaseOrderLine({quantity:3,unit_price:325,total_price:0,product_id:'example'});
assert.equal(persisted.total_price,975);
assert.equal(persisted.unit_price,325);
assert.equal(persisted.product_id,'example');
const vendorChanged=preservePersistedPurchaseOrderOnVendorUpdate(persisted);
assert.deepEqual(vendorChanged,persisted);
assert.notEqual(vendorChanged,persisted);
assert.throws(()=>snapshotPersistedPurchaseOrderLine({quantity:0,unit_price:325,total_price:0}),/Invalid/);
assert.throws(()=>snapshotPersistedPurchaseOrderLine({quantity:1,unit_price:-1,total_price:0}),/Invalid/);
console.log('Purchase order cost snapshot tests passed');
